function check(p,values,{nowIso=null,notProvided='NOT_PROVIDED'}={}){
 const norm=Object.create(null),missing=[],invalid=[];
 const unknown=Object.keys(values).filter(k=>!p.variables.some(v=>v.name===k)).sort();
 for(const v of p.variables){const t=text(values[v.name]).trim();
  if(!t){if(v.required)missing.push(v.name);else norm[v.name]=notProvided;continue;}
  if(t.includes('{{')||t.includes('}}')){invalid.push(v.name+': placeholder braces are not allowed in values');continue;}
  if(v.kind==='DATE'&&!parseInstant(t)){invalid.push(v.name+': not an ISO date (YYYY-MM-DD) or offset-aware ISO datetime');continue;}
  if(v.kind==='INPUT_MODE'&&!MODES.includes(t)){invalid.push('input_mode: not in SYSTEM_CONTEXT/STANDALONE');continue;}
  if(v.kind==='POSITIVE_INT'&&!(/^\d+$/.test(t)&&parseInt(t,10)>0)){invalid.push(v.name+': not a positive integer');continue;}
  norm[v.name]=t;}
 if(norm.as_of){const a=parseInstant(norm.as_of),now=nowIso?new Date(nowIso):new Date();
  if(a>now)invalid.push('as_of: information cutoff lies in the future');
  if(norm.prior_cutoff){const pc=parseInstant(norm.prior_cutoff);if(!(pc<a))invalid.push('prior_cutoff: must be strictly before as_of');}}
 const bad=new Set(invalid.map(s=>s.split(':')[0])),take=n=>n in norm&&!bad.has(n);
 const filled=p.body.replace(PLACEHOLDER,(m,n)=>take(n)?norm[n]:m);
 return{text:filled,missing,invalid,unknown,ready:!(missing.length||invalid.length||unknown.length),take,norm};
}
// ui.py invalidReason: the reason string -> the WORDS key shown under the field.
function reasonKey(reason){
 if(reason.includes('placeholder braces'))return'braces';if(reason.includes('not an ISO date'))return'date';
 if(reason.includes('lies in the future'))return'future';if(reason.includes('strictly before as_of'))return'prior';
 if(reason.includes('not a positive integer'))return'positive';if(reason.includes('not in SYSTEM_CONTEXT/STANDALONE'))return'mode';return'invalid';}

/* ---------------------------------------------------------------- ui.py list(): the list filter (order kept, Bundle in its own order) */
