   const inputs=MODES.map(m=>h('input',{type:'radio',name:id,value:m,required:true,checked:now===m,'aria-describedby':describe,dataset:{v:v.name},onchange:e=>set(V,p,v.name,e.target.value)}));
   V.fields.set(v.name,{inputs,err});
