   const make=h('button',{type:'button',class:'btn',dataset:{promptDraftMake:''},onclick:()=>{
    if(Object.keys(S.drafts).length>=MAX_COPIES){say('내 사본은 '+MAX_COPIES+'개까지입니다. 하나 지운 뒤 만드세요.');return;}
    S.drafts[id]=p.body;paintDraft(V,p);renderList(V);const a=V.draftCard.querySelector('[data-prompt-draft]');if(a)a.focus();}},'공식 원문으로 만들기');
