  const meta=h('p',{class:'note',id:'pd-meta',dataset:{promptDraftMeta:''}});
  const paintMeta=()=>{meta.textContent=(area.value===p.body?'공식 원문과 같음':'공식 원문과 다름')+' · 저장 안 됨 (이 화면에서만) · 글자 수 '+area.value.length.toLocaleString('ko-KR')+' / '+MAX_CHARS.toLocaleString('ko-KR');};
  const fallback=h('textarea',{class:'tbl',readonly:true,hidden:true,rows:'8','aria-label':'복사할 내 사본 · 직접 선택해 복사하세요',dataset:{promptDraftFallback:''}});
  const host=h('div',{hidden:true,dataset:{promptConfirmHost:'draft'}}),ask=h('div',{hidden:true,dataset:{promptDraftResetAsk:''}});
  area.addEventListener('input',()=>{S.drafts[id]=area.value;V.confirmed=null;stale(status,host,fallback);paintMeta();});paintMeta();
  const copy=h('button',{type:'button',class:'btn',dataset:{promptDraftCopy:''},onclick:()=>{
   const body=area.value;if(!body.trim()){say('본문이 비어 있습니다.');return;}
   const r=check({...p,body},valuesOf(p),{notProvided:V.lib.meta.not_provided}),left=[...new Set(r.text.match(/\{\{[a-z_]+\}\}/g)||[])];
   if(!r.ready){say('필수 칸을 먼저 채우세요(공식 원문과 같은 검사).');return;}
   if(left.length){say('선언되지 않은 변수가 남아 있습니다: '+left.join(', '));return;}
   const official=new Set(p.body.split('\n')),added=body.split('\n').filter(l=>!official.has(l)).join('\n');
   doCopy(V,{key:'draft',text:r.text,entries:[...userEntries(V,p),{label:'내 사본에 더한 글',text:added}],status,host,fallback,trigger:copy,ok:'내 사본(공식 원문 아님)을 채워서 복사했습니다.'});}},'채워서 복사');
  const reset=h('button',{type:'button',class:'btn',dataset:{promptDraftReset:''},onclick:()=>{
   ask.replaceChildren(h('p',null,'내 사본을 지울까요? 공식 원문은 그대로 남습니다.'),h('div',{class:'links'},
    h('button',{type:'button',class:'btn solid',dataset:{promptDraftResetConfirm:''},onclick:()=>{delete S.drafts[id];paintDraft(V,p);renderList(V);
     const m=V.draftCard.querySelector('[data-prompt-draft-make]');if(m)m.focus();const st=V.draftCard.querySelector('[data-prompt-draft-status]');if(st)st.textContent='내 사본을 지웠습니다.';}},'지우기'),
    h('button',{type:'button',class:'btn',dataset:{promptDraftResetCancel:''},onclick:()=>{ask.replaceChildren();ask.hidden=true;reset.focus();}},'취소')));
   ask.hidden=false;ask.querySelector('[data-prompt-draft-reset-cancel]').focus();}},'기본값으로 되돌리기');
  V.draftCard.replaceChildren(title,area,meta,
   h('div',{class:'links'},h('button',{type:'button',class:'btn',disabled:true,dataset:{promptDraftSave:''}},'저장 · 준비 중'),copy,reset),ask,status,fallback,host);
